import React, { useState } from 'react';
import Sidebar from '../components/Sidebar';
import TopBar from '../components/TopBar';
import StatsRow from '../components/StatsRow';
import LiveViewPage from './LiveViewPage';
import UsersPage from './UsersPage';
import LogsPage from './LogsPage';
import CameraGrid from '../components/CameraGrid';
import DetectionSummary from '../components/DetectionSummary';
import ChartsRow from '../components/ChartsRow';
import SystemPerf from '../components/SystemPerf';
import SystemPage from './SystemPage';
import AlertsPanel from '../components/AlertsPanel';
import ThresholdPanel from '../components/ThresholdPanel';
import RecordingsPanel from '../components/RecordingsPanel';
import CamerasPage from './CamerasPage';
import GraphsPage from './GraphsPage';
import AlertsPage from './AlertsPage';
import EventsPage from './EventsPage';
import SettingsPage from './SettingsPage';

// ── Placeholder component for pages not built yet ────────────────
function ComingSoon({ title, icon, description }) {
  return (
    <div style={{
      flex:           1,
      display:        'flex',
      flexDirection:  'column',
      alignItems:     'center',
      justifyContent: 'center',
      color:          '#64748b',
      gap:            12
    }}>
      <div style={{ fontSize: 52 }}>{icon}</div>
      <div style={{ fontSize: 18, fontWeight: 700, color: '#e2e8f0' }}>
        {title}
      </div>
      <div style={{ fontSize: 12, color: '#64748b', textAlign: 'center', maxWidth: 300 }}>
        {description}
      </div>
      <div style={{
        background:   '#151d2e',
        border:       '1px solid #1e2d47',
        borderRadius: 8,
        padding:      '8px 20px',
        fontSize:     11,
        color:        '#3b82f6',
        marginTop:    8
      }}>
        Coming in Day 10
      </div>
    </div>
  );
}

// ── Recordings Page — shows all recordings ───────────────────────
function RecordingsPage() {
  const [recordings, setRecordings] = React.useState([]);
  const [loading,    setLoading]    = React.useState(true);

  React.useEffect(() => {
    const load = async () => {
      try {
        const res = await fetch('http://localhost:8000/detections/recordings');
        const data = await res.json();
        setRecordings(data.recordings || []);
      } catch (e) {
        console.warn('[Recordings] Load failed');
      } finally {
        setLoading(false);
      }
    };
    load();
    const id = setInterval(load, 5000);
    return () => clearInterval(id);
  }, []);

  const eventColors = {
    Fire: '#fb923c', Violence: '#f43f5e', Gun: '#f87171',
    Knife: '#facc15', Falling: '#a78bfa', Smoke: '#94a3b8',
    Theft_Mask: '#fbbf24', Normal: '#22c55e'
  };
  const eventIcons = {
    Fire: '🔥', Violence: '⚡', Gun: '🔫',
    Knife: '🔪', Falling: '🏃', Smoke: '💨',
    Theft_Mask: '🎭', Normal: '🛡️'
  };

  return (
    <div style={{ padding: '14px 16px', height: '100%', overflowY: 'auto' }}>
      <div style={{ marginBottom: 16 }}>
        <h2 style={{ fontSize: 16, fontWeight: 700, color: '#fff', margin: 0 }}>
          Recordings
        </h2>
        <p style={{ fontSize: 11, color: '#64748b', margin: '3px 0 0' }}>
          All event recordings — {recordings.length} total
        </p>
      </div>

      {loading ? (
        <div style={{ textAlign: 'center', padding: '40px 0', color: '#64748b' }}>
          Loading recordings...
        </div>
      ) : recordings.length === 0 ? (
        <div style={{
          textAlign: 'center', padding: '80px 0', color: '#64748b'
        }}>
          <div style={{ fontSize: 40, marginBottom: 10 }}>🎬</div>
          <div style={{ fontSize: 14, fontWeight: 600, color: '#e2e8f0' }}>
            No recordings yet
          </div>
          <div style={{ fontSize: 11, marginTop: 4 }}>
            Recordings appear when threats are detected
          </div>
        </div>
      ) : (
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap: 12
        }}>
          {recordings.map((rec, i) => {
            const color = eventColors[rec.event_type] || '#94a3b8';
            const icon  = eventIcons[rec.event_type]  || '⚠️';
            return (
              <div key={i} style={{
                background:   '#151d2e',
                border:       `1px solid ${color}33`,
                borderRadius: 8,
                overflow:     'hidden'
              }}>
                {/* Thumbnail */}
                <div style={{
                  height:         120,
                  background:     `linear-gradient(135deg, #0a0e1a, ${color}22)`,
                  display:        'flex',
                  alignItems:     'center',
                  justifyContent: 'center',
                  fontSize:       40
                }}>
                  {icon}
                  {rec.status === 'recording' && (
                    <span style={{
                      position:     'absolute',
                      top:          8, right: 8,
                      background:   '#450a0a',
                      color:        '#f87171',
                      fontSize:     9,
                      padding:      '2px 6px',
                      borderRadius: 3,
                      fontWeight:   700
                    }}>● REC</span>
                  )}
                </div>

                {/* Info */}
                <div style={{ padding: '10px 12px' }}>
                  <div style={{ fontSize: 12, fontWeight: 700, color }}>
                    {rec.event_type} Detected
                  </div>
                  <div style={{ fontSize: 10, color: '#64748b', marginTop: 3 }}>
                    {rec.camera_name}
                  </div>
                  <div style={{ fontSize: 10, color: '#475569', marginTop: 2 }}>
                    {rec.timestamp}
                  </div>
                  <div style={{
                    display:        'flex',
                    justifyContent: 'space-between',
                    alignItems:     'center',
                    marginTop:      8
                  }}>
                    <span style={{ fontSize: 10, color: '#64748b' }}>
                      {rec.duration} {rec.size_mb > 0 ? `• ${rec.size_mb} MB` : ''}
                    </span>
                    {rec.status === 'complete' && (
                      <button
                        onClick={() => {
                          const a    = document.createElement('a');
                          a.href     = `http://localhost:8000/detections/recordings/download/${rec.filename}`;
                          a.download = rec.filename;
                          a.click();
                        }}
                        style={{
                          background:   '#1e3a5f',
                          border:       '1px solid #253550',
                          color:        '#60a5fa',
                          padding:      '4px 10px',
                          borderRadius: 4,
                          fontSize:     10,
                          cursor:       'pointer'
                        }}
                      >
                        ⬇ Download
                      </button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}


// Pages with no right panel
const FULL_WIDTH_PAGES = [
  'Cameras', 'Graphs', 'Alerts',
  'Events', 'Settings', 'Recordings',
  'Live View', 'Users', 'Logs', 'System'
];

export default function Dashboard() {
  const [activePage, setActivePage] = useState('Dashboard');
  const isFullWidth = FULL_WIDTH_PAGES.includes(activePage);

  const renderMain = () => {
    switch (activePage) {
      case 'Dashboard':
        return (
          <div style={{ flex: 1, overflowY: 'auto', padding: '10px 12px' }}>
            <CameraGrid />
            <DetectionSummary />
            <ChartsRow />
            <SystemPerf />
          </div>
        );
      case 'Live View':
        return <LiveViewPage />;
      case 'Cameras':
        return <CamerasPage />;
      case 'Events':
        return <EventsPage />;
      case 'Recordings':
        return <RecordingsPage />;
      case 'Graphs':
        return <GraphsPage />;
      case 'Alerts':
        return <AlertsPage />;
      case 'Settings':
        return <SettingsPage />;
      case 'System':
        return <SystemPage />;
      case 'Logs':
        return <LogsPage />;
      case 'Users':
        return <UsersPage />;
      
      
      default:
        return (
          <comingSoon
            title={activePage}
            icon="🔧"
            description="404 - This page is still under construction. Please check back later!"
          />
        );
    }
  };

  return (
    <div style={{
      display:             'grid',
      gridTemplateColumns: isFullWidth ? '200px 1fr' : '200px 1fr 280px',
      height:              '100vh',
      overflow:            'hidden',
      background:          '#0a0e1a'
    }}>
      {/* SIDEBAR */}
      <Sidebar
        activePage={activePage}
        setActivePage={setActivePage}
      />

      
      {/* MAIN */}
      <div style={{
        display:       'flex',
        flexDirection: 'column',
        overflow:      'hidden'
      }}>
        <TopBar
          activePage={activePage}
          setActivePage={setActivePage}
        />
        <StatsRow />
        {renderMain()}
      </div>

      {/* RIGHT PANEL — sirf dashboard pe */}
      {!isFullWidth && (
        <div style={{
          background:    '#111827',
          borderLeft:    '1px solid #1e2d47',
          display:       'flex',
          flexDirection: 'column',
          overflow:      'hidden'
        }}>
          <AlertsPanel />
          <ThresholdPanel />
          <RecordingsPanel />
        </div>
      )}
    </div>
  );
}
